export function insideRegion(x,z,polygons){const inRing=(ring)=>{let inside=false;for(let i=0,j=ring.length-1;i<ring.length;j=i++){const a=ring[i],b=ring[j];if((a[1]>z)!==(b[1]>z)&&x<(b[0]-a[0])*(z-a[1])/(b[1]-a[1])+a[0])inside=!inside;}return inside;};return polygons.some(p=>inRing(p.outer)&&!p.holes.some(inRing));}
function surface(k,material,data,elevation,name,marker){const p=[],uv=[];for(const [x,z]of data.vertices){p.push(x,elevation(x,z),z);uv.push(x/2,z/2);}const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(p,3));g.setAttribute('uv',new T.Float32BufferAttribute(uv,2));g.setIndex(data.indices);g.computeVertexNormals();const mesh=k.mesh(g,material,name);mesh.castShadow=false;mesh.userData={villageTrafficSurface:marker,trafficRevision:43};return mesh;}
function curbFaces(k,m){const p=[],uv=[],ix=[],vertices=new Map(),vertex=(x,z,top)=>{const key=x+','+z+','+top;if(!vertices.has(key)){vertices.set(key,p.length/3);p.push(x,roadSurfaceHeight(x,z)+(top?curbLift(x,z):0),z);uv.push(x/2,z/2);}return vertices.get(key);};for(const poly of TRAFFIC.curb.polygons)for(const ring of [poly.outer,...poly.holes])for(let i=0;i<ring.length;i++){const a=ring[i],b=ring[(i+1)%ring.length],dx=b[0]-a[0],dz=b[1]-a[1],length=Math.hypot(dx,dz);if(length<1e-6)continue;const x=(a[0]+b[0])/2,z=(a[1]+b[1])/2,nx=-dz/length,nz=dx/length;let sign=insideRegion(x+nx*.025,z+nz*.025,TRAFFIC.road.polygons)?1:insideRegion(x-nx*.025,z-nz*.025,TRAFFIC.road.polygons)?-1:0;if(!sign)continue;const at=vertex(...a,true),ab=vertex(...a,false),bt=vertex(...b,true),bb=vertex(...b,false);if(sign>0)ix.push(at,ab,bt,bt,ab,bb);else ix.push(at,bt,ab,bt,bb,ab);}const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(p,3));g.setAttribute('uv',new T.Float32BufferAttribute(uv,2));g.setIndex(ix);g.computeVertexNormals();const face=k.mesh(g,m.ivory,'Geschlossene senkrechte Bordsteinflächen');face.userData={villageCurbFace:true};}
